!function(){
  const legacy=document.createElement('script');
  legacy.src='assets/site-pro-legacy.min.js?v=20261003-5';
  legacy.onload=function(){setTimeout(enhanceStorefront,0)};
  document.head.appendChild(legacy);

  async function enhanceStorefront(){
    if(document.getElementById('woongbi-storefront-deals')) return;

    const style=document.createElement('style');
    style.id='woongbi-storefront-style';
    style.textContent=`
      #woongbi-storefront-deals{padding:54px 0 58px;background:#f7fafb;border-top:1px solid #e1eaec;border-bottom:1px solid #e1eaec}
      .storefront-head{display:flex;justify-content:space-between;gap:28px;align-items:end;margin-bottom:24px}
      .storefront-head h2{margin:0;font-size:clamp(1.8rem,3vw,2.5rem);line-height:1.25}
      .storefront-head p{margin:8px 0 0;color:var(--muted);font-size:.96rem;max-width:680px}
      .storefront-head .storefront-all{flex:0 0 auto;color:var(--teal);font-weight:900;text-decoration:underline;text-underline-offset:4px}
      .deal-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
      .deal-card{text-decoration:none;color:inherit;display:flex;flex-direction:column;min-width:0;overflow:hidden;border:1px solid #d7e1e5;border-radius:20px;background:#fff;box-shadow:0 10px 28px rgba(16,60,82,.06);transition:transform .18s ease,box-shadow .18s ease;cursor:pointer}
      .deal-card:hover{transform:translateY(-3px);box-shadow:0 16px 34px rgba(16,60,82,.11)}
      .deal-card:focus-visible{outline:3px solid rgba(15,118,110,.28);outline-offset:3px}
      .deal-media{height:158px;display:flex;align-items:center;justify-content:center;position:relative;background:linear-gradient(145deg,#f4f8f8,#fff)}
      .deal-media img{display:block;max-width:90%;max-height:146px;object-fit:contain}
      .deal-device-icon{font-size:4.5rem;filter:drop-shadow(0 10px 18px rgba(16,60,82,.12))}
      .deal-tag{position:absolute;left:12px;top:12px;display:inline-flex;padding:5px 9px;border-radius:999px;background:#103c52;color:#fff;font-size:.7rem;font-weight:900}
      .deal-body{display:flex;flex:1;flex-direction:column;padding:18px}
      .deal-carrier{font-size:.76rem;font-weight:900;color:var(--teal)}
      .deal-card h3{font-size:1.12rem;line-height:1.4;margin:4px 0 0}
      .deal-plan{display:block;margin-top:7px;color:var(--muted);font-size:.82rem;line-height:1.5}
      .deal-price{display:block;margin-top:14px;padding-top:13px;border-top:1px solid #e5ecee}
      .deal-price small{display:block;color:var(--muted);font-size:.72rem;margin-bottom:2px}
      .deal-price strong{font-size:1.55rem;letter-spacing:-.04em;color:#103c52}
      .deal-price strong span{font-size:.78rem;letter-spacing:0;margin-left:3px}
      .deal-fit{margin-top:9px;font-size:.78rem;line-height:1.5;color:#536a75;min-height:2.4em}
      .deal-link{margin-top:auto;padding-top:15px;color:var(--teal);font-size:.82rem;font-weight:900}
      .deal-note{margin-top:18px;padding:13px 15px;border-radius:13px;background:#eef6f5;color:#536a75;font-size:.79rem;line-height:1.58}
      .deal-note strong{color:#163341}
      @media(max-width:980px){.deal-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
      @media(max-width:640px){
        #woongbi-storefront-deals{padding:38px 0 42px}
        .storefront-head{display:block;margin-bottom:18px}.storefront-head .storefront-all{display:inline-block;margin-top:10px;font-size:.82rem}
        .deal-grid{display:flex;overflow-x:auto;gap:11px;scroll-snap-type:x mandatory;padding:0 1px 9px;-webkit-overflow-scrolling:touch}.deal-grid::-webkit-scrollbar{display:none}
        .deal-card{flex:0 0 min(76vw,270px);scroll-snap-align:start}.deal-media{height:138px}.deal-media img{max-height:126px}.deal-device-icon{font-size:4rem}
        .deal-body{padding:16px}.deal-card h3{font-size:1.03rem}.deal-price strong{font-size:1.42rem}.deal-note{font-size:.73rem}
        .rate-calculator-cta{order:-1}
      }
    `;
    document.head.appendChild(style);

    const section=document.createElement('section');
    section.id='woongbi-storefront-deals';
    section.setAttribute('aria-label','웅비통신 휴대폰 상담 견적 예시');
    section.innerHTML=`
      <div class="wrap">
        <div class="storefront-head">
          <div><p class="eyebrow">처음 보면 여기부터</p><h2>어떤 휴대폰이 맞을지,<br>추천 기종부터 살펴보세요.</h2><p>계산기와 같은 최신 데이터로 부모님용·가성비·프리미엄 후보를 골랐습니다. 번호이동 · 24개월 · 복지할인 미적용 기준입니다.</p></div>
          <a class="storefront-all" href="/rates.html">전체 기종·요금제 알아보기 →</a>
        </div>
        <div class="deal-grid" aria-live="polite"><p>추천 기종을 불러오는 중입니다.</p></div>
        <p class="deal-note"><strong>꼭 확인해 주세요.</strong> 추천 기종은 상담을 시작하기 위한 예시입니다. 실제 월 예상금액은 가입유형, 요금제, 할인 자격, 지원금, 재고 및 프로모션에 따라 달라져 계산기와 매장에서 최종 확인합니다.</p>
      </div>`;

    const hero=document.querySelector('.hero');
    if(hero) hero.insertAdjacentElement('afterend',section);
    const grid=section.querySelector('.deal-grid');
    try{
      const engine=window.WoongbiRecommendationV2;
      await engine.ready;
      if(!engine.status().ready)throw new Error('recommendations unavailable');
      const rows=[...engine.recommend('senior').slice(0,2).map(c=>({...c,label:'부모님용'})),...engine.recommend('value').slice(0,1).map(c=>({...c,label:'가성비'})),...engine.recommend('premium').slice(0,1).map(c=>({...c,label:'프리미엄'}))];
      const won=n=>Math.round(n).toLocaleString('ko-KR')+'원';
      grid.replaceChildren();
      rows.forEach(c=>{
        const card=document.createElement('a');card.className='deal-card';card.href=engine.detailUrl(c);card.dataset.deviceId=c.d.id;card.dataset.planId=c.p.id;
        const media=document.createElement('div');media.className='deal-media';const tag=document.createElement('span');tag.className='deal-tag';tag.textContent=c.label;media.append(tag);
        const image=window.woongbiDeviceImage(c.d);if(image){const img=document.createElement('img');img.src=image;img.alt=c.d.name;img.loading='lazy';media.append(img)}else{const icon=document.createElement('span');icon.className='deal-device-icon';icon.textContent='📱';icon.setAttribute('aria-hidden','true');media.append(icon)}
        const body=document.createElement('div');body.className='deal-body';
        const add=(tag,cls,text)=>{const el=document.createElement(tag);el.className=cls;el.textContent=text;body.append(el);return el};
        add('span','deal-carrier',c.d.carrier+' · '+c.join);add('h3','',c.d.name);
        add('p','deal-plan',c.p.name+' · 월 '+won(c.p.monthly_fee));
        const price=add('div','deal-price','');const small=document.createElement('small');small.textContent='예상 월 납부액 · 기기값·통신요금 합계';const total=document.createElement('strong');total.textContent=won(c.best.monthly);price.append(small,total);
        add('p','deal-fit',(c.best.method==='support'?'공시지원':'선택약정 25%')+' · 할부이자 포함 · 복지할인 미적용');
        const tags=window.WoongbiPlanEligibility.labels(c.p);if(tags.length)add('p','deal-fit',tags.join(' · '));
        add('span','deal-link','이 조건으로 계산하기 →');card.append(media,body);grid.append(card);
      });
      const date=document.createElement('p');date.className='deal-note';date.textContent='상품 데이터 '+engine.dataDate()+' 기준 · 계산기와 같은 조건으로 자동 갱신됩니다.';grid.after(date);
    }catch(error){grid.replaceChildren();const link=document.createElement('a');link.className='storefront-fallback-link';link.href='/rates.html';link.textContent='계산기에서 최신 추천 기종 보기 →';grid.append(link);console.warn('Homepage recommendations unavailable',error)}

  }
}();
